import{u as B,r,j as l,N as b}from"./index-Cz2v-cOY.js";import{s as S}from"./subjectConfig-BLILaTzK.js";import{S as R,a as j,b as z}from"./SimulacroResults-Dtp0kHJn.js";const e="geografia-historia",M=[null,{stimulus:"Costa Rica se localiza en el istmo centroamericano, entre los paralelos 8° y 11° de latitud norte. Esta posición ubica al país completamente al norte de la línea ecuatorial y al oeste del meridiano de Greenwich.",source:"Instituto Geográfico Nacional.",question:"De acuerdo con la información anterior, Costa Rica se ubica en los hemisferios",options:["sur y occidental.","norte y oriental.","norte y occidental."],correct:2,mepBloque:e},{stimulus:"Costa Rica limita al norte con Nicaragua y al sureste con Panamá. Esta posición, en el centro del continente americano, convierte al país en un paso obligado entre Norteamérica y Sudamérica.",source:"Atlas de Costa Rica.",question:"Según el texto anterior, ¿qué función geográfica cumple Costa Rica gracias a su ubicación entre dos subcontinentes?",options:["Actúa como puente biológico entre especies de Norteamérica y Sudamérica.","Impide el paso de especies entre Norteamérica y Sudamérica.","Separa completamente la fauna de ambos subcontinentes."],correct:0,mepBloque:e},{stimulus:"Gracias a su posición entre el océano Pacífico y el mar Caribe, Costa Rica cuenta con dos litorales que permiten el comercio internacional y el desarrollo del turismo de playa en ambas costas.",source:"Instituto Costarricense de Turismo.",question:"De acuerdo con el texto, una ventaja de tener costas en dos océanos es que",options:["se reduce la cantidad de especies marinas en el país.","se facilita el comercio y el turismo en ambos litorales.","se elimina el riesgo de fenómenos naturales en las costas."],correct:1,mepBloque:e},{stimulus:"La actividad volcánica de la Cordillera Volcánica Central, combinada con las abundantes lluvias tropicales, ha generado suelos ricos en minerales en buena parte del territorio costarricense.",source:"Ministerio de Agricultura y Ganadería.",question:"Según la información anterior, una consecuencia de la actividad volcánica para la agricultura costarricense es que",options:["los suelos se vuelven menos fértiles cada año.","se favorece la fertilidad de los suelos para el cultivo.","se impide por completo el cultivo en las zonas volcánicas."],correct:1,mepBloque:e},{stimulus:"Costa Rica posee un clima tropical con una estación seca y una lluviosa, además de numerosos microclimas que varían según la altitud y la cercanía al mar.",source:"Instituto Meteorológico Nacional.",question:"De acuerdo con el texto, la variedad de microclimas en Costa Rica favorece principalmente",options:["la disminución de la biodiversidad del país.","la existencia de una gran variedad de flora y fauna.","la eliminación de las estaciones climáticas."],correct:1,mepBloque:e},{stimulus:"Cada año, distintos huracanes y tormentas tropicales que se forman en el océano Atlántico provocan fuertes lluvias en la vertiente del Pacífico costarricense, debido a la circulación de los vientos.",source:"Instituto Meteorológico Nacional.",question:"Según el texto, este fenómeno representa una desventaja relacionada con",options:["la posición geográfica del país y su exposición a fenómenos climáticos.","la forma irregular de las costas del país.","la falta de biodiversidad en el territorio nacional."],correct:0,mepBloque:e},{stimulus:"El terreno montañoso y la actividad de las placas tectónicas hacen que Costa Rica sea un país con alta actividad sísmica, donde los movimientos de tierra pueden ocasionar daños en la infraestructura.",source:"Red Sismológica Nacional.",question:"De acuerdo con el texto, ¿a qué fenómeno natural hace referencia la información anterior?",options:["Sequías","Terremotos","Erupciones volcánicas"],correct:1,mepBloque:e},{stimulus:"Cuando las lluvias son muy intensas, los ríos de las llanuras costarricenses pueden desbordarse y provocar daños en viviendas y cultivos, además de deslizamientos en zonas montañosas.",source:"Comisión Nacional de Emergencias.",question:"Según la información, el texto describe principalmente",options:["inundaciones causadas por el exceso de lluvia.","sequías provocadas por la falta de lluvia.","erupciones causadas por la actividad volcánica."],correct:0,mepBloque:e},{stimulus:"La Cordillera de Talamanca es la más extensa y elevada de Costa Rica. En ella se encuentra el cerro Chirripó, la montaña más alta del país.",source:"Sistema Nacional de Áreas de Conservación.",question:"De acuerdo con el texto anterior, ¿cuál característica distingue a la Cordillera de Talamanca de las demás cordilleras del país?",options:["Es la cordillera más pequeña y baja del territorio.","Contiene el volcán más activo de Costa Rica.","Es la más larga y alta, e incluye la montaña más elevada del país."],correct:2,mepBloque:e},{stimulus:"En la región norte de Guanacaste se localiza el volcán Rincón de la Vieja, uno de los principales atractivos de la Cordillera de Guanacaste, conocida por su actividad geotérmica.",source:"Sistema Nacional de Áreas de Conservación.",question:"Según el texto, el volcán Rincón de la Vieja pertenece a la cordillera de",options:["Talamanca.","Guanacaste.","Tilarán."],correct:1,mepBloque:e},{stimulus:"Entre la Cordillera de Guanacaste y la zona norte del país se ubica la Cordillera de Tilarán, donde los fuertes vientos han favorecido la instalación de plantas de energía eólica.",source:"Instituto Costarricense de Electricidad.",question:"De acuerdo con el texto, la Cordillera de Tilarán se localiza entre",options:["la Cordillera de Guanacaste y la zona norte.","la Cordillera de Talamanca y el Caribe.","el Pacífico y la Cordillera Volcánica Central."],correct:0,mepBloque:e},{stimulus:"El Valle Central, ubicado entre montañas, concentra la mayor parte de la población costarricense y de las actividades agrícolas e industriales del país, en parte porque por él pasan importantes ríos.",source:"Instituto Nacional de Estadística y Censos.",question:"Según la información anterior, una razón por la que el Valle Central concentra tanta población es que",options:["los valles son terrenos altos y de difícil acceso.","los valles son terrenos bajos, fértiles y con acceso a ríos.","los valles carecen de tierras aptas para la agricultura."],correct:1,mepBloque:e},{stimulus:"Las Llanuras del Caribe y las del Norte son zonas planas y bajas, cercanas al nivel del mar, cuyos suelos son ideales para actividades agrícolas y ganaderas a gran escala.",source:"Ministerio de Agricultura y Ganadería.",question:"De acuerdo con el texto, ¿cuál es la principal característica de las llanuras costarricenses?",options:["Son terrenos altos y rocosos sin uso agrícola.","Son terrenos planos y fértiles, aptos para la agricultura.","Son terrenos volcánicos sin posibilidad de cultivo."],correct:1,mepBloque:e},{stimulus:"Costa Rica posee costas en el océano Pacífico y en el mar Caribe; algunas presentan playas extensas, mientras otras tienen acantilados o desembocaduras de ríos.",source:"Instituto Costarricense de Turismo.",question:"Según el texto, ¿cuáles son los dos litorales que conforman las costas de Costa Rica?",options:["El Pacífico y el Atlántico Norte.","El Caribe y el Golfo de México.","El Pacífico y el mar Caribe."],correct:2,mepBloque:e},{stimulus:"Debido a su pequeño tamaño territorial, una persona puede desplazarse desde la costa del Pacífico hasta la costa del Caribe en pocas horas, lo que favorece el turismo y la diversidad de experiencias en un mismo viaje.",source:"Instituto Costarricense de Turismo.",question:"De acuerdo con el texto, el tamaño territorial de Costa Rica representa una ventaja porque",options:["impide conocer ambas costas en un solo viaje.","permite recorrer ambas costas en poco tiempo.","limita el desarrollo del turismo en el país."],correct:1,mepBloque:e},{stimulus:"Los primeros habitantes de Costa Rica, hace aproximadamente 12 000 años, no contaban con viviendas fijas. Se desplazaban de un lugar a otro siguiendo a los animales que cazaban para alimentarse.",source:"Museo Nacional de Costa Rica.",question:"Según el texto, ¿cómo se describe el estilo de vida de los primeros pobladores del territorio costarricense?",options:["Sedentario, viviendo siempre en el mismo lugar.","Nómada, desplazándose en busca de alimento.","Urbano, organizado en grandes ciudades."],correct:1,mepBloque:e},{stimulus:"La evidencia arqueológica de los primeros cazadores y recolectores de Costa Rica se ha encontrado principalmente en las regiones de Guanacaste y Turrialba, donde se hallaron herramientas de piedra.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿en qué regiones se ha hallado mayor evidencia de los primeros pobladores?",options:["Limón y Puntarenas.","Guanacaste y Turrialba.","Cartago y Heredia."],correct:1,mepBloque:e},{stimulus:"Los primeros pobladores cazaban grandes animales hoy extintos, conocidos como megafauna, entre los que se encontraban el armadillo gigante, el perezoso gigante y el mastodonte.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué tipo de animales formaban parte de la dieta de los primeros pobladores?",options:["Megafauna, como el mastodonte y el perezoso gigante.","Animales domésticos traídos de Europa.","Únicamente peces y aves marinas."],correct:0,mepBloque:e},{stimulus:"Alrededor del año 2000 a.C., los habitantes del territorio costarricense aprendieron a sembrar maíz, frijoles y yuca, lo que les permitió establecerse en un mismo lugar y formar las primeras aldeas.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué cambio provocó el desarrollo de la agricultura en los pobladores de esa época?",options:["El abandono total de los cultivos.","El paso de la vida nómada a la vida en aldeas permanentes.","El regreso a la caza como única actividad."],correct:1,mepBloque:e},{stimulus:"Durante el período de los aldeanos igualitarios, todos los miembros de la comunidad compartían la tierra y los productos de la cosecha; no existían personas con más riquezas que otras.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cómo era la propiedad de la tierra en esta etapa?",options:["Privada, cada familia poseía grandes extensiones.","Colectiva, compartida por toda la comunidad.","Exclusiva del cacique de la aldea."],correct:1,mepBloque:e},{stimulus:"Entre el año 500 y el 1500 d.C., las sociedades del territorio costarricense se volvieron más complejas: aparecieron líderes llamados caciques y guías religiosos llamados chamanes.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué caracterizó a la sociedad de los aldeanos cacicales?",options:["La ausencia total de líderes o jerarquías.","La aparición de líderes políticos y religiosos y la diferenciación social.","El regreso a una vida nómada sin asentamientos."],correct:1,mepBloque:e},{stimulus:"Durante la etapa cacical, los objetos de jade se convirtieron en adornos muy valorados que indicaban el rango social de quien los portaba dentro de la comunidad.",source:"Museo del Jade.",question:"Según la información anterior, ¿qué función cumplían los objetos de jade en las sociedades cacicales?",options:["Servían como moneda de intercambio comercial.","Indicaban el rango social de las personas.","Se utilizaban únicamente para cazar animales."],correct:1,mepBloque:e},{stimulus:"Los chorotegas, asentados principalmente en la región de Guanacaste, consideraban al maíz como una divinidad y realizaban ceremonias y comidas especiales relacionadas con este cultivo.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué relación tenían los chorotegas con el maíz?",options:["Lo consideraban un alimento prohibido.","Lo veneraban como una divinidad.","No lo incluían en su dieta diaria."],correct:1,mepBloque:e},{stimulus:"El pueblo huetar, asentado en la región central del país, rendía culto al Sol y a la Luna mediante danzas, cantos y la construcción de altares de piedra.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿a qué elementos rendían culto principalmente los huetares?",options:["Al Sol y a la Luna.","A los ríos y a las montañas.","Únicamente a sus antepasados."],correct:0,mepBloque:e},{stimulus:"Entre los cabécares, un sacerdote llamado Jawá cumplía la función de intermediario entre el mundo espiritual y el mundo físico de la comunidad.",source:"Centro de Investigación y Conservación del Patrimonio Cultural.",question:"De acuerdo con el texto, ¿cuál era la función del Jawá entre los cabécares?",options:["Liderar las batallas militares de la comunidad.","Servir de intermediario entre lo espiritual y lo físico.","Organizar el comercio con otras etnias."],correct:1,mepBloque:e},{stimulus:"Los bribris realizan la danza ancestral del Sorbón, en la cual hombres y mujeres forman un gran círculo que simboliza la solidaridad y la pertenencia a la tierra.",source:"Centro de Investigación y Conservación del Patrimonio Cultural.",question:"Según la información anterior, ¿qué simboliza la danza del Sorbón para el pueblo bribri?",options:["La solidaridad y la pertenencia a la tierra.","La rivalidad entre distintas comunidades.","La celebración del fin de la cosecha de café."],correct:0,mepBloque:e},{stimulus:"Cada 31 de diciembre, el pueblo brunca o boruca celebra el Baile de los Diablitos, una manifestación cultural en la que los participantes confeccionan máscaras artesanales.",source:"Ministerio de Cultura y Juventud.",question:"De acuerdo con el texto, ¿qué elemento artesanal es central en la celebración del Baile de los Diablitos?",options:["Las máscaras confeccionadas por la comunidad.","Los instrumentos musicales de cuerda.","Las vasijas de barro decoradas."],correct:0,mepBloque:e},{stimulus:"El pueblo maleku, asentado en la zona norte del país, entierra a sus muertos dentro de las viviendas porque cree que los espíritus continúan influyendo de manera benéfica sobre la familia.",source:"Centro de Investigación y Conservación del Patrimonio Cultural.",question:"Según la información anterior, ¿por qué el pueblo maleku entierra a sus muertos dentro de las viviendas?",options:["Porque consideran que los espíritus siguen ayudando a la familia.","Porque no cuentan con terrenos disponibles fuera de la vivienda.","Porque es una práctica impuesta por los misioneros españoles."],correct:0,mepBloque:e},{stimulus:'Los térrabas consideran que la roca conocida como "la Mano de Tigre", ubicada en una montaña cercana a su comunidad, es un elemento venerado que forma parte de su identidad cultural.',source:"Centro de Investigación y Conservación del Patrimonio Cultural.",question:'De acuerdo con el texto, ¿qué representa "la Mano de Tigre" para el pueblo térraba?',options:["Un elemento natural venerado por la comunidad.","Una construcción realizada por los españoles.","Un instrumento musical tradicional."],correct:0,mepBloque:e},{stimulus:"Las mujeres del pueblo ngäbe o guaymí confeccionan chácaras, que son bolsas tejidas a mano, además de collares elaborados con cuentas, conchas y huesos.",source:"Centro de Investigación y Conservación del Patrimonio Cultural.",question:"Según la información anterior, ¿qué objeto artesanal confeccionan tradicionalmente las mujeres ngäbes?",options:["Vasijas de cerámica policroma.","Chácaras o bolsas tejidas.","Instrumentos musicales de viento."],correct:1,mepBloque:e},{stimulus:'Muchas palabras que usamos hoy en el español de Costa Rica, como "aguacate", "elote" y "chocolate", provienen de las lenguas de los pueblos originarios.',source:"Academia Costarricense de la Lengua.",question:"De acuerdo con el texto, ¿qué aporte de los pueblos originarios se describe en la información anterior?",options:["Técnicas de construcción de viviendas.","Palabras incorporadas al español costarricense.","Instrumentos de trabajo agrícola."],correct:1,mepBloque:e},{stimulus:"Las esferas de piedra del Diquís, elaboradas por los pueblos precolombinos del sur de Costa Rica, fueron declaradas Patrimonio de la Humanidad por su valor histórico y cultural.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué reconocimiento internacional recibieron las esferas de piedra del Diquís?",options:["Fueron declaradas Patrimonio de la Humanidad.","Fueron destruidas por su antigüedad.","Fueron trasladadas a un museo en España."],correct:0,mepBloque:e},{stimulus:"Muchas comunidades indígenas de Costa Rica enfrentan actualmente dificultades para acceder a escuelas y centros de salud cercanos, debido a la falta de buenas vías de comunicación hacia sus territorios.",source:"Fondo de las Naciones Unidas para la Infancia.",question:"De acuerdo con el texto, ¿cuál es uno de los desafíos actuales de los pueblos originarios de Costa Rica?",options:["El exceso de escuelas y hospitales en sus territorios.","La falta de vías de comunicación hacia servicios básicos.","La prohibición total de practicar sus costumbres."],correct:1,mepBloque:e},{stimulus:"Diversas organizaciones señalan que muchas comunidades indígenas costarricenses todavía enfrentan pobreza y pocas oportunidades económicas, por lo que se promueven proyectos para mejorar el comercio en sus territorios.",source:"Fondo de las Naciones Unidas para la Infancia.",question:"Según la información anterior, ¿qué se busca con los proyectos mencionados en el texto?",options:["Reducir el comercio en los territorios indígenas.","Aumentar las oportunidades económicas de las comunidades indígenas.","Eliminar las tradiciones culturales de los pueblos originarios."],correct:1,mepBloque:e},{stimulus:"La cerámica de los pueblos originarios de Costa Rica incluía piezas con formas de figuras humanas, llamadas antropomorfas, y con formas de animales, llamadas zoomorfas.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué tipos de formas se destacan en la cerámica indígena costarricense?",options:["Formas geométricas únicamente.","Formas antropomorfas y zoomorfas.","Formas exclusivamente religiosas europeas."],correct:1,mepBloque:e},{stimulus:"En 1502, durante su cuarto viaje, Cristóbal Colón llegó por primera vez a las costas del actual territorio costarricense, lo que marcó el inicio del contacto entre españoles y pueblos originarios.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿en qué año se produjo el primer contacto entre Cristóbal Colón y el territorio costarricense?",options:["1492","1502","1575"],correct:1,mepBloque:e},{stimulus:"España necesitaba nuevos mercados para vender sus productos, buscaba oro y otros metales preciosos, y deseaba expandir la religión católica entre los pueblos de América.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuáles fueron algunas de las causas de la conquista española en América?",options:["La búsqueda de nuevos mercados, oro y la expansión religiosa.","El interés de los pueblos indígenas por comerciar con Europa.","La necesidad de aprender nuevas lenguas indígenas."],correct:0,mepBloque:e},{stimulus:"El terreno montañoso, el clima tropical húmedo y la resistencia de los pueblos indígenas hicieron que la conquista del territorio costarricense fuera más lenta que en otras regiones de América.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué factores dificultaron el avance de la conquista española en Costa Rica?",options:["La ausencia total de población indígena.","El terreno, el clima y la resistencia indígena.","La falta de armas de fuego entre los españoles."],correct:1,mepBloque:e},{stimulus:"Tras la llegada de los españoles, la población indígena de Costa Rica disminuyó drásticamente debido a enfermedades como la viruela y el sarampión, así como a los trabajos forzados impuestos.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuáles fueron causas de la disminución de la población indígena durante la conquista?",options:["Las enfermedades europeas y los trabajos forzados.","La emigración voluntaria hacia otros países.","El aumento en la producción de alimentos."],correct:0,mepBloque:e},{stimulus:"Con la llegada de los españoles se introdujeron nuevos cultivos como el trigo, el arroz y la caña de azúcar, además de animales de granja como caballos, vacas y cerdos.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué elementos introdujeron los españoles en el territorio costarricense durante la conquista?",options:["Nuevos cultivos y animales de granja.","Instrumentos musicales indígenas.","Técnicas de pesca artesanal."],correct:0,mepBloque:e},{stimulus:"La mezcla entre españoles, indígenas y, posteriormente, personas de origen africano dio origen a nuevas etnias con costumbres propias dentro del territorio costarricense.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cómo se denomina el proceso descrito en la información anterior?",options:["Independencia","Mestizaje","Colonización"],correct:1,mepBloque:e},{stimulus:"Durante el período colonial, Costa Rica fue una pequeña provincia que dependía de la Capitanía General de Guatemala, la cual, a su vez, formaba parte del Virreinato de Nueva España.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿de qué entidad política dependía directamente la provincia de Costa Rica durante la colonia?",options:["De la Capitanía General de Guatemala.","Del Virreinato del Perú.","Del Reino de Nicaragua."],correct:0,mepBloque:e},{stimulus:"Durante la colonia, Cartago fue designada como la capital de la provincia de Costa Rica, sede del gobernador y centro de la vida política y religiosa del territorio.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuál ciudad fungió como capital de Costa Rica durante el período colonial?",options:["San José","Cartago","Limón"],correct:1,mepBloque:e},{stimulus:"Al ser una de las provincias más alejadas del centro administrativo colonial, Costa Rica sufrió aislamiento económico, escasez de metales preciosos y poca disponibilidad de mano de obra indígena.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué consecuencia tuvo para Costa Rica el estar alejada del centro administrativo colonial?",options:["Un rápido crecimiento económico y comercial.","Aislamiento económico y escasez de recursos.","Una mayor cantidad de metales preciosos disponibles."],correct:1,mepBloque:e},{stimulus:"Durante la colonia se utilizaron tres formas principales de aprovechar la tierra: la chacra, para el consumo familiar; la plantación, orientada al comercio; y la hacienda, dedicada a la ganadería y la agricultura en gran escala.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuál de estas formas de uso de la tierra estaba orientada principalmente al comercio?",options:["La chacra","La plantación","La hacienda"],correct:1,mepBloque:e},{stimulus:"La exportación de ganado, cacao y tabaco fue una de las principales actividades económicas de Costa Rica durante la época colonial, sostenida primero por mano de obra indígena y luego por esclavos africanos.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con la información anterior, la economía colonial costarricense se caracterizó por",options:["depender únicamente del comercio con Europa.","usar mano de obra indígena y, después, esclava africana.","prohibir cualquier tipo de exportación agrícola."],correct:1,mepBloque:e},{stimulus:"Durante la colonia, la sociedad costarricense estaba organizada de manera jerárquica: en la cima se ubicaban los peninsulares y sus descendientes, mientras que mestizos, indígenas y esclavos ocupaban los niveles más bajos.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿en qué se basaba principalmente la posición social durante la época colonial?",options:["En el nivel educativo de cada persona.","En el origen y el color de piel de las personas.","En la cantidad de tierras heredadas por igual."],correct:1,mepBloque:e},{stimulus:"Bajo el sistema de la encomienda, un grupo de personas indígenas trabajaba las tierras de un español llamado encomendero, quien debía, en teoría, cuidar su salud y alimentación.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué era la encomienda durante la colonia?",options:["Un sistema en el que indígenas trabajaban para un encomendero español.","Una escuela donde se enseñaba a los indígenas a leer.","Un impuesto que pagaban los españoles a la Corona."],correct:0,mepBloque:e},{stimulus:"Durante la colonia, los esclavos de origen africano trabajaron principalmente en plantaciones de cacao, en la ganadería, en la construcción de caminos e iglesias, y en labores domésticas.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿en qué actividades se empleaba principalmente a las personas esclavizadas de origen africano?",options:["En plantaciones, ganadería, construcción y labores domésticas.","Únicamente en la administración del gobierno colonial.","Solo en la enseñanza religiosa a los indígenas."],correct:0,mepBloque:e},{stimulus:"La Iglesia Católica tuvo un papel central durante la colonia: organizó fiestas religiosas, controló la educación bajo principios morales y religiosos, e influyó fuertemente en el arte de la época.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué institución tuvo un papel central en la vida social y cultural durante el período colonial?",options:["El Cabildo Municipal.","La Iglesia Católica.","El Tribunal Supremo de Elecciones."],correct:1,mepBloque:e},{stimulus:"El 15 de septiembre de 1821, las provincias centroamericanas, entre ellas Costa Rica, proclamaron su independencia de España, dando inicio a una nueva etapa política en la región.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué evento ocurrió el 15 de septiembre de 1821?",options:["Se firmó el Pacto de Concordia.","Centroamérica proclamó su independencia de España.","Se anexó el Partido de Nicoya a Costa Rica."],correct:1,mepBloque:e},{stimulus:"La noticia de la independencia de Centroamérica tardó casi un mes en llegar a Cartago, debido a la falta de medios rápidos de comunicación en la época.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿por qué la noticia de la independencia tardó en llegar a Costa Rica?",options:["Porque Costa Rica decidió no participar del proceso.","Porque no existían medios rápidos de comunicación.","Porque España bloqueó la noticia durante varios años."],correct:1,mepBloque:e},{stimulus:"Las ideas de la Ilustración europea, que defendían la libertad y la igualdad, junto con el descontento de los criollos por no poder ocupar cargos importantes, impulsaron el deseo de independencia en Centroamérica.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuáles fueron causas de la independencia centroamericana?",options:["Las ideas de la Ilustración y el descontento de los criollos.","El aumento del comercio entre España y sus colonias.","La desaparición de la Iglesia Católica en América."],correct:0,mepBloque:e},{stimulus:"España exigía que sus colonias comerciaran únicamente con la Corona española, lo que limitaba el desarrollo económico de provincias como Costa Rica.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cómo se denomina la práctica comercial descrita en el texto?",options:["Libre comercio","Monopolio comercial","Comercio justo"],correct:1,mepBloque:e},{stimulus:"A diferencia de otros procesos de independencia en América, el de Costa Rica se caracterizó por el diálogo entre los habitantes, sin enfrentamientos armados significativos.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cómo se caracteriza el proceso de independencia de Costa Rica?",options:["Como un proceso violento y prolongado.","Como un proceso pacífico, basado en el diálogo.","Como una invasión extranjera."],correct:1,mepBloque:e},{stimulus:"En 1823, surgió un conflicto entre quienes en Cartago apoyaban la unión con México y quienes en San José y Alajuela preferían la independencia total de Centroamérica.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué grupos se enfrentaron en la Batalla de Ochomogo?",options:["Costa Rica contra Nicaragua.","Quienes apoyaban la unión a México y quienes querían la independencia total.","Los filibusteros contra el ejército costarricense."],correct:1,mepBloque:e},{stimulus:"Tras el triunfo de San José y Alajuela en el conflicto de 1823, la sede del gobierno costarricense se trasladó de Cartago a San José, ciudad que se convirtió en la nueva capital.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué consecuencia tuvo la Batalla de Ochomogo para la organización política de Costa Rica?",options:["El traslado de la capital de Cartago a San José.","La anexión inmediata del Partido de Nicoya.","La firma del Pacto de Concordia."],correct:0,mepBloque:e},{stimulus:"En 1824, Costa Rica adoptó la Ley Fundamental del Estado Libre de Costa Rica, que estableció la separación de poderes y un sistema de gobierno republicano.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué estableció la Ley Fundamental del Estado Libre de Costa Rica en 1824?",options:["La separación de poderes y un gobierno republicano.","La unión definitiva con el Imperio Mexicano.","El fin de la esclavitud en el territorio nacional."],correct:0,mepBloque:e},{stimulus:"El 1° de diciembre de 1821, una junta de legados redactó un documento que organizó el funcionamiento del nuevo Estado costarricense, estableciendo un gobierno formado por una Junta Superior Gubernativa de siete miembros.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿a qué documento histórico hace referencia la información anterior?",options:["La Constitución de 1871.","El Pacto de Concordia.","La Ley Fundamental de 1824."],correct:1,mepBloque:e},{stimulus:"El Pacto de Concordia, también conocido como Pacto Social Fundamental Interino de Costa Rica, declaró la religión católica y el idioma español como oficiales del nuevo Estado.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué declaró oficialmente el Pacto de Concordia?",options:["El idioma inglés y la religión protestante.","La religión católica y el idioma español.","La abolición de la esclavitud."],correct:1,mepBloque:e},{stimulus:"El Pacto de Concordia estuvo vigente solamente durante dos años, pero su importancia histórica permanece porque fue el primer documento que organizó políticamente a Costa Rica como Estado libre.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿por qué se considera importante el Pacto de Concordia a pesar de su corta vigencia?",options:["Porque fue la primera Constitución Política del país.","Porque continúa vigente en la actualidad.","Porque estableció la independencia definitiva de México."],correct:0,mepBloque:e},{stimulus:"En 1824, el Partido de Nicoya, que anteriormente pertenecía a Nicaragua, decidió de manera voluntaria unirse al territorio de Costa Rica.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cómo se llevó a cabo la anexión del Partido de Nicoya a Costa Rica?",options:["Mediante una invasión militar costarricense.","De manera voluntaria, por decisión de sus habitantes.","Por orden directa del gobierno español."],correct:1,mepBloque:e},{stimulus:'La anexión del Partido de Nicoya enriqueció la cultura costarricense con canciones folclóricas como "El Torito" y "Pasión", además de instrumentos como la marimba y los quijongos.',source:"Ministerio de Cultura y Juventud.",question:"De acuerdo con el texto, ¿qué aporte cultural trajo la anexión del Partido de Nicoya a Costa Rica?",options:["El folclor musical, con canciones e instrumentos tradicionales.","La eliminación de las tradiciones costarricenses previas.","La prohibición de cultivos agrícolas en la zona."],correct:0,mepBloque:e},{stimulus:"La incorporación de Guanacaste también trajo tierras fértiles para el cultivo de arroz, caña de azúcar y sorgo, así como para el desarrollo de la ganadería.",source:"Ministerio de Agricultura y Ganadería.",question:"Según la información anterior, ¿qué aporte económico trajo la anexión del Partido de Nicoya?",options:["Tierras fértiles para la agricultura y la ganadería.","La eliminación del comercio agrícola del país.","Recursos minerales para la exportación."],correct:0,mepBloque:e},{stimulus:"A lo largo del siglo XX, el derecho al voto en Costa Rica evolucionó: en 1913 se estableció el voto directo, en 1925 el voto secreto, y en 1949 y 1952 se otorgó este derecho a las mujeres.",source:"Tribunal Supremo de Elecciones.",question:"De acuerdo con el texto, ¿en qué años obtuvieron las mujeres costarricenses el derecho al voto?",options:["1913 y 1925","1949 y 1952","1821 y 1824"],correct:1,mepBloque:e},{stimulus:"Entre 1856 y 1857, un grupo de mercenarios extranjeros, conocidos como filibusteros y liderados por William Walker, intentó apoderarse de Centroamérica, lo que llevó a Costa Rica a organizar su defensa.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿quién lideraba el grupo de mercenarios que invadió Centroamérica?",options:["Juan Rafael Mora Porras.","William Walker.","Juan Santamaría."],correct:1,mepBloque:e},{stimulus:"El presidente Juan Rafael Mora Porras organizó y lideró la defensa nacional costarricense ante la amenaza de los filibusteros, logrando que personas de distintas clases sociales se unieran a la lucha.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿quién organizó la defensa de Costa Rica durante la Campaña Nacional?",options:["Juan Santamaría.","Juan Rafael Mora Porras.","William Walker."],correct:1,mepBloque:e},{stimulus:"El 20 de marzo de 1856, en la hacienda Santa Rosa de Guanacaste, las fuerzas costarricenses enfrentaron al ejército filibustero en un combate que duró apenas entre 15 y 20 minutos.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿en qué lugar se desarrolló la primera batalla de la Campaña Nacional?",options:["En la hacienda Santa Rosa, Guanacaste.","En el fuerte de San Carlos.","En la ciudad de Rivas, Nicaragua."],correct:0,mepBloque:e},{stimulus:"Tras una carga de bayonetas en la hacienda Santa Rosa, los filibusteros huyeron derrotados en dirección a la ciudad nicaragüense de Rivas.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué táctica utilizaron los costarricenses para derrotar a los filibusteros en Santa Rosa?",options:["Una carga de bayonetas.","Un ataque con artillería pesada.","Un asedio prolongado de varios meses."],correct:0,mepBloque:e},{stimulus:"Para asegurar una posición estratégica contra los filibusteros, una columna de 300 soldados costarricenses cruzó el río San Juan el 7 de abril de 1856 y ocupó territorio nicaragüense.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué objetivo tenía el cruce del río San Juan por parte de las tropas costarricenses?",options:["Retirarse definitivamente del conflicto.","Asegurar una posición estratégica contra los filibusteros.","Establecer relaciones comerciales con Nicaragua."],correct:1,mepBloque:e},{stimulus:"En la Batalla de Rivas, ocurrida el 11 de abril de 1856, los filibusteros se atrincheraron en un edificio conocido como el Mesón, desde donde atacaban a las fuerzas costarricenses.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué táctica utilizó el ejército costarricense para desalojar a los filibusteros del Mesón en Rivas?",options:["Excavar un túnel hacia el edificio.","Incendiar el edificio donde se refugiaban.","Negociar una rendición pacífica."],correct:1,mepBloque:e},{stimulus:"Juan Santamaría, un tamborilero originario de Alajuela, se ofreció voluntariamente para incendiar el Mesón de Guerra durante la Batalla de Rivas, logrando que los filibusteros se retiraran.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué reconocimiento recibió Juan Santamaría por su acción en Rivas?",options:["Fue declarado Héroe Nacional de Costa Rica.","Fue nombrado presidente de la República.","Fue exiliado del país por su acción."],correct:0,mepBloque:e},{stimulus:"El 22 de diciembre de 1856, en el sitio conocido como la Vía del Tránsito, donde se unen el río San Juan y el lago de Nicaragua, el ejército costarricense tomó posiciones que marcaron el principio del fin de la presencia filibustera.",source:"Ministerio de Cultura y Juventud.",question:"En el contexto de la Campaña Nacional, ¿a cuál combate hace referencia el texto anterior?",options:["Batalla de Santa Rosa.","Combate de la Trinidad.","Batalla de Sardinal."],correct:1,mepBloque:e},{stimulus:"El 30 de diciembre de 1856, las fuerzas costarricenses lograron tomar el fuerte de San Carlos, un punto estratégico que conectaba con el lago de Nicaragua a través del río San Juan.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿por qué era estratégico el fuerte de San Carlos para el control del territorio?",options:["Porque conectaba con el lago de Nicaragua a través del río San Juan.","Porque era la capital administrativa de los filibusteros.","Porque allí se ubicaba el gobierno costarricense."],correct:0,mepBloque:e},{stimulus:"La Campaña Nacional unió a costarricenses de distintas clases sociales y regiones del país en defensa de su territorio, fortaleciendo la identidad nacional y consolidando la independencia proclamada en 1821.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cuál fue uno de los principales legados de la Campaña Nacional para Costa Rica?",options:["El debilitamiento del sentido de identidad nacional.","El fortalecimiento de la identidad nacional y la unión del país.","La división del país en distintas regiones independientes."],correct:1,mepBloque:e},{stimulus:"A finales del siglo XIX, Costa Rica vivió un proceso de cambios conocido como las Reformas Liberales, orientado a modernizar el Estado y reducir la influencia de la Iglesia Católica en la vida pública.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cuál era uno de los principales objetivos de las Reformas Liberales?",options:["Fortalecer el poder de la Iglesia Católica.","Modernizar el Estado y reducir la influencia eclesiástica.","Restaurar el sistema colonial español."],correct:1,mepBloque:e},{stimulus:"La Constitución Política de 1871 mantuvo la división de poderes, pero otorgó mayor fuerza al Poder Ejecutivo, permitiendo al presidente nombrar y remover gobernadores y secretarios de Estado.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué cambio introdujo la Constitución de 1871 respecto al Poder Ejecutivo?",options:["Eliminó por completo la figura del presidente.","Le otorgó mayor poder e influencia al presidente.","Trasladó todas sus funciones al Poder Legislativo."],correct:1,mepBloque:e},{stimulus:"Durante las Reformas Liberales, el Estado expulsó al obispo Bernardo Augusto Thiel y a los jesuitas, además de prohibir las órdenes monásticas y la enseñanza religiosa en instituciones estatales.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cómo se conoce al conjunto de medidas que limitaron el poder de la Iglesia Católica durante esta época?",options:["Garantías Sociales","Leyes anticlericales","Ley Fundamental del Estado"],correct:1,mepBloque:e},{stimulus:"Como parte de las leyes anticlericales, los cementerios pasaron de estar bajo control eclesiástico a ser administrados por el Estado.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué cambio describe la información anterior?",options:["La secularización de los cementerios.","La construcción de nuevos templos religiosos.","El aumento del poder político de la Iglesia."],correct:0,mepBloque:e},{stimulus:"A finales del siglo XIX, el licenciado Mauro Fernández Acuña impulsó una reforma educativa que centralizó el sistema escolar bajo el Ministerio de Instrucción Pública, en lugar de dejarlo a cargo de cada municipalidad por separado.",source:"Sandoval, A. (2009).",question:"De acuerdo con el texto anterior, ¿qué acción de las Reformas Liberales ayudó a fortalecer la enseñanza en todo el territorio nacional?",options:["El mantenimiento de la autonomía municipal en la educación.","La centralización del sistema educativo bajo un ministerio.","La eliminación total de las escuelas primarias."],correct:1,mepBloque:e},{stimulus:"Gracias a las Reformas Liberales, la educación primaria en Costa Rica pasó a ser gratuita, obligatoria, laica y financiada por el Estado, garantizando el acceso sin distinción de religión o clase social.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué características adquirió la educación primaria costarricense con las Reformas Liberales?",options:["Privada, opcional y costeada por las familias.","Gratuita, obligatoria, laica y costeada por el Estado.","Exclusiva para estudiantes de clases sociales altas."],correct:1,mepBloque:e},{stimulus:"Durante las Reformas Liberales se fundaron importantes centros de educación secundaria, como el Instituto de Alajuela, el Liceo de Costa Rica y el Colegio de Señoritas.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿cuáles instituciones educativas se crearon durante las Reformas Liberales?",options:["La Universidad de Costa Rica y el Colegio de Señoritas.","El Instituto de Alajuela, el Liceo de Costa Rica y el Colegio de Señoritas.","La Escuela Normal y el Instituto Tecnológico."],correct:1,mepBloque:e},{stimulus:"Como parte del impulso a la educación y la cultura, durante las Reformas Liberales se fundaron la Biblioteca Nacional y el Archivo Nacional de Costa Rica.",source:"Sistema Nacional de Bibliotecas.",question:"De acuerdo con el texto, ¿qué instituciones culturales se fundaron durante las Reformas Liberales?",options:["La Biblioteca Nacional y el Archivo Nacional.","El Museo Nacional y el Teatro Nacional.","La Casa Presidencial y el Tribunal Supremo de Elecciones."],correct:0,mepBloque:e},{stimulus:"El café se convirtió en el principal producto de exportación de Costa Rica durante las Reformas Liberales, generando riqueza que permitió desarrollar nueva infraestructura en el país.",source:"Instituto del Café de Costa Rica.",question:"Según la información anterior, ¿qué producto impulsó el desarrollo económico durante las Reformas Liberales?",options:["El cacao","El café","El banano"],correct:1,mepBloque:e},{stimulus:"Para transportar el café desde el Valle Central hasta el puerto de Limón en el Caribe, Costa Rica construyó una vía férrea que facilitó el comercio internacional del país.",source:"Instituto Costarricense de Ferrocarriles.",question:"De acuerdo con el texto, ¿qué obra de infraestructura se construyó para facilitar la exportación del café?",options:["El Canal de Panamá.","El ferrocarril al Caribe.","Una carretera hacia Nicaragua."],correct:1,mepBloque:e},{stimulus:"Durante la década de 1940, el presidente Rafael Ángel Calderón Guardia impulsó importantes reformas sociales con el apoyo de la Iglesia Católica, representada por monseñor Víctor Manuel Sanabria, y del Partido Comunista Costarricense, liderado por Manuel Mora Valverde.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué actores apoyaron al presidente Calderón Guardia en sus reformas sociales?",options:["La Iglesia Católica y el Partido Comunista Costarricense.","El gobierno de Estados Unidos y empresas extranjeras.","Los partidos de oposición conservadora."],correct:0,mepBloque:e},{stimulus:"La Caja Costarricense de Seguro Social, creada en 1941, se financia con aportes de los trabajadores, los patronos y el Estado, lo que permitió construir clínicas y hospitales públicos en todo el país.",source:"Caja Costarricense de Seguro Social.",question:"De acuerdo con el texto, ¿cómo se financia la Caja Costarricense de Seguro Social?",options:["Únicamente con fondos del Estado.","Con aportes de trabajadores, patronos y el Estado.","Con donaciones de organizaciones internacionales."],correct:1,mepBloque:e},{stimulus:"Gracias a la creación de la Caja Costarricense de Seguro Social en 1941, fue posible aumentar la esperanza de vida de la población y reducir la mortalidad infantil en el país.",source:"Caja Costarricense de Seguro Social.",question:"Según la información anterior, ¿qué beneficios trajo la creación de la CCSS para la población costarricense?",options:["El aumento de la mortalidad infantil.","El aumento de la esperanza de vida y la reducción de la mortalidad infantil.","La disminución del acceso a la salud pública."],correct:1,mepBloque:e},{stimulus:"El Código de Trabajo de 1943 estableció una jornada laboral de 48 horas semanales, el derecho a vacaciones pagadas y la prohibición del trabajo infantil en Costa Rica.",source:"Ministerio de Trabajo y Seguridad Social.",question:"De acuerdo con el texto, ¿cuáles derechos laborales estableció el Código de Trabajo de 1943?",options:["Jornada de 48 horas semanales, vacaciones pagadas y prohibición del trabajo infantil.","Jornadas laborales sin límite de horas.","La eliminación del salario mínimo."],correct:0,mepBloque:e},{stimulus:"Las Garantías Sociales, integradas en la Constitución Política en 1942, incluyeron el derecho a la sindicalización, la negociación colectiva y la seguridad social para los trabajadores costarricenses.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿en qué año se integraron las Garantías Sociales a la Constitución Política?",options:["1940","1942","1949"],correct:1,mepBloque:e},{stimulus:"En 1941, el gobierno de Calderón Guardia fundó la Universidad de Costa Rica para preparar a los profesionales que el país necesitaba, después de que la antigua Universidad de Santo Tomás había cerrado durante la época liberal.",source:"Universidad de Costa Rica.",question:"De acuerdo con el texto, ¿qué institución de educación superior se fundó en 1941?",options:["El Instituto Tecnológico de Costa Rica.","La Universidad de Costa Rica.","La Universidad Nacional."],correct:1,mepBloque:e},{stimulus:"En las elecciones presidenciales del 8 de febrero de 1948, el candidato Otilio Ulate Blanco resultó vencedor frente al candidato oficialista, lo que generó una fuerte disputa política en el país.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué ocurrió en las elecciones presidenciales de febrero de 1948?",options:["Otilio Ulate resultó ganador frente al candidato del gobierno.","Se reformó la Constitución Política del país.","Se abolió el ejército costarricense."],correct:0,mepBloque:e},{stimulus:"Tras las elecciones de 1948, el Congreso, controlado por los seguidores del gobierno, anuló los resultados electorales, lo que generó un fuerte descontento entre los seguidores de Otilio Ulate.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué decisión del Congreso provocó el descontento que llevó al conflicto armado de 1948?",options:["La anulación de los resultados de las elecciones.","La creación de la Caja Costarricense de Seguro Social.","La firma de la Constitución de 1871."],correct:0,mepBloque:e},{stimulus:'Ante la anulación de los resultados electorales, José Figueres Ferrer organizó un grupo armado conocido como el Ejército de Liberación Nacional desde su finca llamada "La Lucha", iniciando así un conflicto armado en el país.',source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿quién lideró el levantamiento armado tras la anulación de las elecciones de 1948?",options:["Otilio Ulate Blanco.","José Figueres Ferrer.","Rafael Ángel Calderón Guardia."],correct:1,mepBloque:e},{stimulus:"El conflicto armado de 1948 se desarrolló durante varias semanas en distintas regiones del país, con enfrentamientos en zonas como San Isidro de El General y Cartago.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿cómo se conoce este conflicto armado ocurrido en Costa Rica en 1948?",options:["La Campaña Nacional.","La Guerra Civil de 1948.","Las Reformas Liberales."],correct:1,mepBloque:e},{stimulus:"El conflicto armado de 1948 finalizó con la firma de un acuerdo de paz en la embajada de México, mediante el cual las partes enfrentadas acordaron poner fin a la confrontación.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿dónde se firmó el acuerdo que puso fin a la Guerra Civil de 1948?",options:["En el Cuartel Bellavista.","En la embajada de México.","En el Congreso de la República."],correct:1,mepBloque:e},{stimulus:"Tras la Guerra Civil de 1948, se estableció una Junta Fundadora de la Segunda República, liderada por José Figueres Ferrer, encargada de gobernar el país durante un período de transición.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué entidad gobernó Costa Rica durante el período de transición posterior a la Guerra Civil de 1948?",options:["La Junta Fundadora de la Segunda República.","El Congreso controlado por Calderón Guardia.","El gobierno provisional de Otilio Ulate."],correct:0,mepBloque:e},{stimulus:"El 1° de diciembre de 1948, en un acto simbólico realizado en el antiguo Cuartel Bellavista, se anunció la disolución del ejército costarricense como institución permanente.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué decisión histórica se anunció el 1° de diciembre de 1948?",options:["La creación de un nuevo ejército nacional.","La abolición del ejército como institución permanente.","La firma del Pacto de Concordia."],correct:1,mepBloque:e},{stimulus:"El antiguo Cuartel Bellavista, donde se anunció la abolición del ejército, fue transformado posteriormente en un espacio cultural dedicado a la conservación de la historia del país.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿en qué institución se convirtió el antiguo Cuartel Bellavista?",options:["En la sede del Tribunal Supremo de Elecciones.","En el Museo Nacional de Costa Rica.","En la nueva Casa Presidencial."],correct:1,mepBloque:e},{stimulus:"La nueva Constitución Política, promulgada en 1949 tras la Guerra Civil, mantuvo las Garantías Sociales establecidas en la década de 1940 e incluyó un artículo que prohíbe el mantenimiento de un ejército permanente en el país.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿qué aspectos incluyó la Constitución Política de 1949?",options:["La eliminación de las Garantías Sociales y la creación de un nuevo ejército.","El mantenimiento de las Garantías Sociales y la prohibición de un ejército permanente.","El regreso al sistema colonial español."],correct:1,mepBloque:e}],m=a=>a.map(o=>({...M[o]})),P=m([1,16,36,51,66,76,86,2,17,37,52,67,77,87,3,18,38,53,68,78,88,4,19,39,54,69,79,89,5,20,40,55,70,80,90]),N=m([6,21,41,56,71,81,91,7,22,42,57,72,82,92,8,23,43,58,73,83,93,9,24,44,59,74,84,94,10,25,45,60,75,85,95]),D=m([11,26,46,61,96,12,27,47,62,97,13,28,48,63,98,14,29,49,64,99,15,30,50,65,100,31,32,33,34,35]),I=[{stimulus:"Costa Rica se localiza en el istmo centroamericano, entre los paralelos 8° y 11° de latitud norte. Esta posición ubica al país completamente al norte de la línea ecuatorial y al oeste del meridiano de Greenwich.",source:"Instituto Geográfico Nacional.",question:"De acuerdo con la información anterior, Costa Rica se ubica en los hemisferios",options:["norte y occidental.","sur y occidental.","norte y oriental."],correct:0,mepBloque:e},{stimulus:"Los primeros habitantes de Costa Rica, hace aproximadamente 12 000 años, no contaban con viviendas fijas. Se desplazaban de un lugar a otro siguiendo a los animales que cazaban para alimentarse.",source:"Museo Nacional de Costa Rica.",question:"Según el texto, ¿cómo se describe el estilo de vida de los primeros pobladores del territorio costarricense?",options:["Nómada, desplazándose en busca de alimento.","Sedentario, viviendo siempre en el mismo lugar.","Urbano, organizado en grandes ciudades."],correct:0,mepBloque:e},{stimulus:"En 1502, durante su cuarto viaje, Cristóbal Colón llegó por primera vez a las costas del actual territorio costarricense, lo que marcó el inicio del contacto entre españoles y pueblos originarios.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿en qué año se produjo el primer contacto entre Cristóbal Colón y el territorio costarricense?",options:["1502","1492","1575"],correct:0,mepBloque:e},{stimulus:"El 15 de septiembre de 1821, las provincias centroamericanas, entre ellas Costa Rica, proclamaron su independencia de España, dando inicio a una nueva etapa política en la región.",source:"Museo Nacional de Costa Rica.",question:"De acuerdo con el texto, ¿qué evento ocurrió el 15 de septiembre de 1821?",options:["Centroamérica proclamó su independencia de España.","Se firmó el Pacto de Concordia.","Se anexó el Partido de Nicoya a Costa Rica."],correct:0,mepBloque:e},{stimulus:"Entre 1856 y 1857, un grupo de mercenarios extranjeros, conocidos como filibusteros y liderados por William Walker, intentó apoderarse de Centroamérica, lo que llevó a Costa Rica a organizar su defensa.",source:"Museo Nacional de Costa Rica.",question:"Según la información anterior, ¿quién lideraba el grupo de mercenarios que invadió Centroamérica?",options:["William Walker.","Juan Rafael Mora Porras.","Juan Santamaría."],correct:0,mepBloque:e}],G=[...D,...I],A=[P,N,G],T=[null,{stimulus:"La sangre es un tejido líquido formado por varios componentes. Uno de ellos es un líquido amarillento compuesto por agua, sales, proteínas y vitaminas que sirve para transportar las células sanguíneas por todo el cuerpo.",source:"Ministerio de Educación Pública de Costa Rica.",question:"De acuerdo con la información anterior, el componente de la sangre que se describe es el",options:["glóbulo rojo.","glóbulo blanco.","plasma."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"En clase de Ciencias, la maestra explica que cuando el cuerpo sufre un corte, ciertos componentes de la sangre actúan de inmediato para detener el sangrado y formar una costra protectora sobre la herida.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según la información anterior, los componentes de la sangre que intervienen en este proceso son las",options:["vitaminas.","plaquetas.","proteínas."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"Los glóbulos rojos contienen una proteína de color rojo que les permite transportar el oxígeno desde los pulmones hasta todas las células del cuerpo. Esta proteína le da a la sangre su característico color rojo.",source:"Atlas de Ciencias para Primaria.",question:"De acuerdo con el texto, la proteína que se encuentra en los glóbulos rojos y que transporta el oxígeno se llama",options:["hemoglobina.","leucocito.","trombocito."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"Una estudiante de sexto grado se realizó un examen de sangre. El médico le explicó que cuando el organismo está combatiendo una infección causada por bacterias, la cantidad de un tipo de célula sanguínea aumenta considerablemente para defender el cuerpo.",source:"Guía de Salud Escolar, MEP.",question:"Según la información anterior, las células cuya cantidad aumenta durante una infección son los",options:["glóbulos rojos.","trombocitos.","glóbulos blancos."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Las vacunas son sustancias que se aplican al cuerpo para estimular la producción de proteínas defensoras. Gracias a ellas, cuando la persona entra en contacto con la enfermedad en el futuro, su organismo ya sabe cómo combatirla.",source:"Ministerio de Salud de Costa Rica.",question:"Según el texto, la función principal de las vacunas es",options:["curar enfermedades que ya están desarrolladas en el organismo.","eliminar directamente los microorganismos del cuerpo.","preparar al organismo para defenderse de enfermedades futuras."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"En una campaña de salud escolar se indicó que ciertas enfermedades que antes causaban miles de muertes han desaparecido casi por completo gracias a programas de vacunación masiva a nivel mundial.",source:"Organización Panamericana de la Salud.",question:"De acuerdo con la información anterior, uno de los beneficios más importantes de las vacunas es que permiten",options:["reducir el precio de los medicamentos.","erradicar enfermedades contagiosas mortales.","sustituir los tratamientos médicos en hospitales."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"En clase de Ciencias, los estudiantes aprendieron sobre los sistemas del cuerpo humano. El sistema que se encarga de transformar los alimentos en sustancias más simples que pueden pasar a la sangre y nutrir las células recibe un nombre específico.",source:"Libro de Ciencias, Morfho Editorial.",question:"El sistema que se describe en el texto anterior es el sistema",options:["circulatorio.","renal.","digestivo."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"El hígado es un órgano que produce una sustancia verdosa que se encarga de procesar las grasas que ingresan con los alimentos. Además, ayuda a controlar los niveles de colesterol en la sangre.",source:"Atlas de Ciencias para Primaria.",question:"Según el texto, la sustancia producida por el hígado que se describe es la",options:["insulina.","bilis.","saliva."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"El corazón realiza dos movimientos al funcionar: en uno de ellos se contrae para expulsar la sangre hacia los vasos sanguíneos; en el otro, se dilata para recibir la sangre que regresa de los tejidos del cuerpo.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información anterior, el movimiento del corazón cuando se contrae para expulsar la sangre se llama",options:["sístole.","diástole.","válvula."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"Los vasos sanguíneos encargados de transportar los desechos y el dióxido de carbono desde los tejidos del cuerpo de vuelta hacia el corazón reciben un nombre específico. Son de color más oscuro que las arterias.",source:"Libro de Ciencias, Morfho Editorial.",question:"Los vasos sanguíneos que se describen en el texto son las",options:["arterias.","capilares.","venas."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"El sistema respiratorio cumple una función fundamental para que el organismo pueda vivir. Uno de sus procesos consiste en tomar el oxígeno del aire para que llegue a la sangre y expulsar el dióxido de carbono que producen las células.",source:"Ministerio de Educación Pública de Costa Rica.",question:"La función descrita en el texto anterior se llama",options:["digestión.","intercambio gaseoso.","filtración sanguínea."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"Una estructura del sistema respiratorio funciona como una válvula que se abre y se cierra para evitar que los alimentos que tragamos lleguen accidentalmente a los pulmones. Es fundamental en el momento de deglutir.",source:"Atlas de Ciencias para Primaria.",question:"La estructura que se describe en el texto es la",options:["laringe.","tráquea.","epiglotis."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Los riñones filtran la sangre constantemente a través de estructuras microscópicas. El líquido resultante de ese proceso de filtración es almacenado en un órgano específico hasta que el cuerpo lo expulsa al exterior.",source:"Libro de Ciencias, Morfho Editorial.",question:"El órgano que almacena la orina hasta su expulsión es la",options:["uretra.","nefrona.","vejiga."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"El sistema nervioso controla todas las funciones del cuerpo. Está formado por células altamente especializadas que transmiten impulsos eléctricos a lo largo de una red de comunicación extensa que conecta el cerebro con todos los órganos.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información anterior, las células que forman el sistema nervioso y transmiten los impulsos eléctricos se llaman",options:["plaquetas.","eritrocitos.","neuronas."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Esta estructura del sistema nervioso se encuentra en la parte inferior del cerebro. Se encarga de coordinar los movimientos musculares para que sean precisos y fluidos, como caminar, escribir o tocar un instrumento musical.",source:"Atlas de Ciencias para Primaria.",question:"La estructura que se describe en el texto es el",options:["bulbo raquídeo.","cerebro.","cerebelo."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"En el cuerpo humano hay un sistema formado por glándulas que fabrican sustancias químicas llamadas mensajeros. Estas sustancias viajan por la sangre llevando instrucciones de una parte del cuerpo a otra.",source:"Libro de Ciencias, Morfho Editorial.",question:"El sistema que se describe en el texto es el sistema",options:["nervioso.","circulatorio.","endocrino."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Un estudiante de sexto grado aprendió que los malos hábitos afectan los sistemas del cuerpo. Por ejemplo, consumir exceso de azúcar y grasas puede dañar un órgano encargado de producir una hormona que regula el nivel de azúcar en la sangre.",source:"Ministerio de Salud de Costa Rica.",question:"Según el texto, el órgano que puede dañarse por el consumo excesivo de azúcar y que produce insulina es el",options:["hígado.","páncreas.","riñón."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"Los sistemas del cuerpo humano no trabajan de forma independiente. Por ejemplo, cuando los pulmones toman el oxígeno del aire, necesitan de otro sistema para que ese oxígeno llegue a todas las células del organismo.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, el sistema que trabaja junto con el respiratorio para distribuir el oxígeno a las células es el sistema",options:["digestivo.","renal.","circulatorio."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Una médica le explicó a sus pacientes que existen procedimientos modernos mediante los cuales un órgano enfermo puede ser reemplazado por uno sano proveniente de otra persona, lo que puede salvar vidas en casos críticos.",source:"Caja Costarricense de Seguro Social.",question:"El procedimiento médico que se describe en el texto se llama",options:["clonación.","trasplante de órganos.","vacunación."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"En una clínica, una doctora utilizó un aparato que emite ondas de alta frecuencia para observar el interior del cuerpo de una paciente embarazada sin necesidad de realizarle ninguna cirugía.",source:"Caja Costarricense de Seguro Social.",question:"El aparato médico descrito en el texto se llama",options:["bomba de cobalto.","ultrasonido.","rayos X."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"El sistema reproductor femenino cumple varias funciones. Una de ellas es producir las células sexuales femeninas que, al unirse con las células sexuales masculinas, pueden dar origen a un nuevo ser humano.",source:"Libro de Ciencias, Morfho Editorial.",question:"Las células sexuales femeninas que se producen en los ovarios se llaman",options:["óvulos.","espermatozoides.","embriones."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"La médula espinal tiene dos funciones principales: transmitir mensajes entre el cerebro y el resto del cuerpo, y coordinar las respuestas inmediatas que el cuerpo realiza ante situaciones de peligro sin que el cerebro tenga que ordenarlas.",source:"Atlas de Ciencias para Primaria.",question:"Las respuestas rápidas del cuerpo que describe el texto, que no requieren intervención directa del cerebro, se llaman",options:["impulsos.","hormonas.","actos reflejos."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Cuando el sistema inmunitario del cuerpo detecta la entrada de microorganismos dañinos como bacterias o virus, activa mecanismos de defensa para eliminarlos. Uno de esos mecanismos consiste en producir proteínas especiales que neutralizan a los invasores.",source:"Ministerio de Salud de Costa Rica.",question:"Las proteínas defensoras del cuerpo que se mencionan en el texto se llaman",options:["hormonas.","plaquetas.","anticuerpos."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Las arterias son vasos sanguíneos que tienen paredes gruesas y elásticas porque la sangre que circula por ellas proviene directamente del corazón y lo hace con mucha presión, llevando oxígeno y nutrientes a todos los tejidos.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según el texto, la función principal de las arterias es",options:["transportar la sangre con dióxido de carbono hacia el corazón.","almacenar la sangre en los órganos principales.","llevar la sangre con oxígeno desde el corazón hacia los tejidos."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"El intestino delgado es el órgano donde ocurre la mayor parte del proceso de absorción de sustancias nutritivas. Desde ahí, esas sustancias pasan directamente a un sistema que las distribuye por todo el organismo.",source:"Libro de Ciencias, Morfho Editorial.",question:"El sistema que recibe los nutrientes del intestino delgado y los distribuye por el cuerpo es el sistema",options:["renal.","circulatorio.","nervioso."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:'Una niña le preguntó a su maestra por qué la piel se pone de "gallina" cuando hace frío. La maestra le explicó que esa reacción es controlada por un sistema que regula las respuestas del cuerpo ante estímulos del ambiente, como los cambios de temperatura.',source:"Libro de Ciencias, Morfho Editorial.",question:"El sistema que controla las respuestas del cuerpo ante estímulos como el frío es el sistema",options:["nervioso.","endocrino.","digestivo."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"El bulbo raquídeo es una parte del sistema nervioso que conecta la médula espinal con el encéfalo. Entre sus funciones más importantes está el control de procesos que ocurren de forma automática en el cuerpo, sin que la persona tenga que pensar en ellos.",source:"Atlas de Ciencias para Primaria.",question:"Según el texto, un ejemplo de función que controla el bulbo raquídeo es",options:["memorizar información nueva.","coordinar movimientos al bailar.","regular los latidos del corazón y la respiración."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Los rayos X son una herramienta médica que emite radiaciones capaces de atravesar los tejidos blandos del cuerpo pero que son absorbidas por las estructuras más densas, permitiéndole al médico observarlas en una imagen.",source:"Caja Costarricense de Seguro Social.",question:"Según la información anterior, los rayos X se utilizan principalmente para observar",options:["órganos como el estómago o los intestinos.","estructuras duras del cuerpo como los huesos.","el movimiento del corazón en tiempo real."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"Para mantener el cuerpo sano, es importante seguir ciertas recomendaciones. Una de las más importantes es suministrarle al organismo las vacunas que corresponden en cada etapa de la vida, ya que esto evita enfermedades contagiosas graves.",source:"Ministerio de Salud de Costa Rica.",question:"Según el texto, el principal beneficio de aplicarse las vacunas según el calendario establecido es",options:["aumentar la velocidad de crecimiento del cuerpo.","mejorar el funcionamiento del sistema digestivo.","prevenir enfermedades contagiosas y proteger la salud."],correct:2,mepBloque:"cuerpo-humano"},{stimulus:"Los sistemas del cuerpo humano trabajan juntos para mantener el organismo en funcionamiento. Por ejemplo, el sistema muscular y el sistema óseo actúan de manera coordinada para permitir el movimiento del cuerpo.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, la relación entre el sistema muscular y el sistema óseo sirve para",options:["producir hormonas necesarias para el crecimiento.","posibilitar el movimiento del cuerpo.","filtrar sustancias de desecho de la sangre."],correct:1,mepBloque:"cuerpo-humano"},{stimulus:"La biodiversidad se refiere a la variedad de seres vivos que existe en un lugar determinado. Costa Rica es uno de los países con mayor riqueza biológica del mundo gracias a factores como su posición geográfica y la variedad de sus ecosistemas.",source:"SINAC, Sistema Nacional de Áreas de Conservación.",question:"Según el texto, el término que hace referencia a la variedad de seres vivos en un lugar es",options:["ecosistema.","biodiversidad.","nicho ecológico."],correct:1,mepBloque:"biodiversidad"},{stimulus:"En un bosque viven cientos de aves de la misma especie. Todas ellas comparten el mismo territorio, se alimentan de los mismos recursos y se reproducen entre sí.",source:"Libro de Ciencias, Morfho Editorial.",question:"Al conjunto de individuos de la misma especie que viven en el mismo lugar se le llama",options:["comunidad.","población.","ecosistema."],correct:1,mepBloque:"biodiversidad"},{stimulus:"En el Parque Nacional Corcovado conviven jaguares, tapires, monos, serpientes, cientos de especies de plantas, hongos y microorganismos, todos interactuando entre sí y con el ambiente que los rodea.",source:"SINAC, Sistema Nacional de Áreas de Conservación.",question:"Al conjunto de todos los seres vivos y su ambiente no vivo que interactúan en ese lugar se le llama",options:["población.","comunidad.","ecosistema."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Las plantas son organismos que elaboran su propio alimento a partir de la luz solar, el agua y el dióxido de carbono del ambiente. Este proceso ocurre principalmente en sus hojas y les permite crecer y desarrollarse sin necesitar alimentarse de otros seres vivos.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información anterior, los organismos que producen su propio alimento como las plantas se clasifican como",options:["heterótrofos.","descomponedores.","autótrofos."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Los organismos que no pueden producir su propio alimento deben obtenerlo consumiendo a otros seres vivos. Algunos se alimentan de plantas, otros de animales, y algunos de ambos.",source:"Libro de Ciencias, Morfho Editorial.",question:"Los organismos que obtienen su alimento consumiendo a otros seres vivos se clasifican como",options:["heterótrofos.","autótrofos.","productores."],correct:0,mepBloque:"biodiversidad"},{stimulus:"El pájaro carpintero tiene un pico largo, rígido y en forma de cincel que le permite golpear la madera de los árboles para encontrar insectos que se esconden debajo de la corteza. Esta característica le permite sobrevivir en el bosque.",source:"Atlas de Fauna Costarricense.",question:"La característica del pico del pájaro carpintero descrita en el texto es un ejemplo de adaptación para",options:["la reproducción.","la defensa contra depredadores.","la alimentación."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Algunas ranas de los bosques tropicales poseen colores muy vivos y llamativos, como el rojo, el amarillo o el azul. Estos colores brillantes funcionan como una advertencia para otros animales, indicándoles que son tóxicas y que no deben ser consumidas.",source:"Instituto Nacional de Biodiversidad, INBio.",question:"Los colores llamativos de las ranas venenosas son una adaptación para",options:["atraer a sus presas.","defenderse de sus depredadores.","encontrar pareja durante la reproducción."],correct:1,mepBloque:"biodiversidad"},{stimulus:"Los peces tienen en su cuerpo unas estructuras en forma de láminas que les permiten absorber el oxígeno disuelto en el agua para respirar. Gracias a ellas pueden vivir completamente sumergidos en ríos, lagos y océanos.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Las estructuras que utilizan los peces para respirar bajo el agua se llaman",options:["pulmones.","tráqueas.","branquias."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Las bacterias son organismos microscópicos que están formados por una sola célula. A diferencia de las células de los animales y las plantas, sus células no poseen un núcleo definido o con membrana que separe su material genético del resto del contenido celular.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, las bacterias pertenecen al reino",options:["Protista.","Fungi.","Monera."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Los hongos son organismos que no pueden realizar fotosíntesis, por lo que obtienen sus nutrientes descomponiendo materia orgánica en descomposición o absorbiendo nutrientes de otros seres vivos. Un ejemplo común son los champiñones.",source:"Instituto Nacional de Biodiversidad, INBio.",question:"Los champiñones y otros organismos similares pertenecen al reino",options:["Monera.","Plantae.","Fungi."],correct:2,mepBloque:"biodiversidad"},{stimulus:"La fotosíntesis es el proceso mediante el cual las plantas capturan la energía de la luz solar y la utilizan para transformar el agua y el dióxido de carbono en glucosa. Como resultado de este proceso también se libera oxígeno al ambiente.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información anterior, el gas que se libera al ambiente como resultado de la fotosíntesis es el",options:["dióxido de carbono.","nitrógeno.","oxígeno."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Para que una planta realice el proceso de fotosíntesis necesita ciertos ingredientes del ambiente. Los científicos han identificado tres elementos fundamentales sin los cuales este proceso no puede llevarse a cabo.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, los tres elementos necesarios para la fotosíntesis son",options:["oxígeno, glucosa y sales minerales.","suelo fértil, temperatura cálida y humedad.","luz solar, agua y dióxido de carbono."],correct:2,mepBloque:"biodiversidad"},{stimulus:"En un prado, las plantas producen su propio alimento. Un conejo se alimenta de las plantas. Una serpiente caza y come al conejo.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información anterior, en esta cadena alimentaria la serpiente ocupa el nivel de",options:["productor.","consumidor primario.","consumidor secundario."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Una relación entre dos especies en la que ambas se benefician mutuamente recibe un nombre específico en biología. Un ejemplo es la relación entre las flores y las abejas: las flores brindan néctar a las abejas y estas, al moverse, transportan el polen entre flores.",source:"Instituto Nacional de Biodiversidad, INBio.",question:"La relación entre la flor y la abeja descrita en el texto se clasifica como",options:["parasitismo.","comensalismo.","mutualismo."],correct:2,mepBloque:"biodiversidad"},{stimulus:"En la naturaleza existen relaciones entre organismos en las que uno de ellos se beneficia sin causarle daño ni beneficio al otro. Un ejemplo es el rémora, un pez que se adhiere a los tiburones para alimentarse de sus restos de comida sin perjudicar al tiburón.",source:"Libro de Ciencias, Morfho Editorial.",question:"La relación descrita en el texto se clasifica como",options:["mutualismo.","parasitismo.","comensalismo."],correct:2,mepBloque:"biodiversidad"},{stimulus:"El clima de Costa Rica tiene una influencia directa sobre la gran variedad de seres vivos que habitan el país. La combinación de temperatura, precipitación y humedad crea condiciones favorables para que miles de especies puedan vivir.",source:"SINAC, Sistema Nacional de Áreas de Conservación.",question:"Según el texto, el factor que más favorece la biodiversidad de Costa Rica es",options:["la falta de estaciones climáticas.","la variedad de condiciones climáticas en el territorio.","la escasa presencia de volcanes activos."],correct:1,mepBloque:"biodiversidad"},{stimulus:"La deforestación es la tala masiva de árboles en áreas boscosas para utilizarlos como madera o para convertir los terrenos en zonas agrícolas o urbanas. Esta práctica tiene consecuencias graves para los seres vivos que dependen del bosque para sobrevivir.",source:"Ministerio de Ambiente y Energía, MINAE.",question:"Según el texto, una consecuencia directa de la deforestación para la biodiversidad es",options:["el aumento de la producción de oxígeno en el ambiente.","la pérdida del hábitat de muchas especies animales y vegetales.","la mejora en la calidad del suelo de los bosques."],correct:1,mepBloque:"biodiversidad"},{stimulus:"En una laguna, la proliferación excesiva de algas verdes causó la muerte de numerosos peces. Los científicos explicaron que esto se debió a que las algas consumieron casi todo el oxígeno disuelto en el agua, desequilibrando el ecosistema.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El texto describe una situación en la que el ecosistema perdió su",options:["temperatura habitual.","diversidad de algas.","equilibrio ecológico."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Las lombrices de tierra viven en el suelo y se alimentan de materia orgánica en descomposición. Al hacerlo, ayudan a descomponer los residuos y devuelven nutrientes al suelo, haciéndolo más fértil para las plantas.",source:"Instituto Nacional de Biodiversidad, INBio.",question:"Según el texto, la función ecológica de las lombrices en la cadena alimentaria es la de",options:["productor.","consumidor primario.","descomponedor."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Las plantas de las selvas tropicales responden a los cambios de luz orientando sus tallos y hojas hacia la fuente de luz solar. Esta respuesta de movimiento ante un estímulo lumínico es característica de los vegetales.",source:"Libro de Ciencias, Morfho Editorial.",question:"La respuesta de las plantas al estímulo de la luz que se describe en el texto se llama",options:["simbiosis.","tropismo.","fotosíntesis."],correct:1,mepBloque:"biodiversidad"},{stimulus:"Los hongos del género Penicillium produjeron de forma natural una sustancia que los científicos lograron aislar y utilizar para crear medicamentos capaces de combatir infecciones bacterianas en los seres humanos.",source:"Instituto Nacional de Biodiversidad, INBio.",question:"La sustancia producida por el hongo Penicillium que se usa para combatir infecciones es la",options:["insulina.","penicilina.","bilis."],correct:1,mepBloque:"biodiversidad"},{stimulus:"En una investigación escolar, un grupo de estudiantes encontró en el suelo organismos unicelulares que tenían núcleo definido. Algunos de ellos se movían por sí solos usando estructuras en forma de látigo; otros estaban formados por colonias.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según la información, los organismos descritos pertenecen al reino",options:["Fungi.","Monera.","Protista."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Los invertebrados son animales que carecen de columna vertebral. Entre ellos se encuentran los insectos, los arácnidos, los moluscos y los gusanos. Estos organismos representan la mayor parte de la fauna del planeta.",source:"Atlas de Fauna Costarricense.",question:"Según la información anterior, los arácnidos pertenecen al reino",options:["Fungi.","Plantae.","Animalia."],correct:2,mepBloque:"biodiversidad"},{stimulus:"El calentamiento global ha provocado que las temperaturas de los océanos aumenten, lo que ha causado el blanqueamiento de los arrecifes de coral. Este fenómeno afecta a cientos de especies marinas que dependen del coral para alimentarse y refugiarse.",source:"Ministerio de Ambiente y Energía, MINAE.",question:"El blanqueamiento de los arrecifes de coral es una consecuencia de la ruptura del equilibrio ecológico causada principalmente por",options:["la actividad volcánica submarina.","la pesca excesiva en los arrecifes.","el aumento de la temperatura del océano por el calentamiento global."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Una erupción volcánica puede destruir miles de hectáreas de bosque, acabar con poblaciones de animales y alterar completamente la composición del suelo en una región. Sin embargo, con el tiempo, la vida regresa y coloniza nuevamente el área afectada.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"La erupción volcánica descrita es un ejemplo de evento natural que",options:["mejora permanentemente el ecosistema.","no afecta el equilibrio ecológico.","altera temporalmente el equilibrio ecológico."],correct:2,mepBloque:"biodiversidad"},{stimulus:"Los organismos pluricelulares, como las plantas, están organizados en niveles de complejidad creciente. El primer nivel es la célula; varias células iguales forman el segundo nivel, que realiza una función específica dentro del organismo.",source:"Libro de Ciencias, Morfho Editorial.",question:"El segundo nivel de organización que describe el texto, formado por células iguales que realizan una función específica, se llama",options:["órgano.","tejido.","sistema."],correct:1,mepBloque:"biodiversidad"},{stimulus:"La reproducción asexual es aquella en la que un solo organismo produce descendencia genéticamente idéntica a él mismo, sin necesitar de otro individuo. Un ejemplo son los organismos que se reproducen por bipartición o fragmentación.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según el texto, la principal característica de la reproducción asexual es que",options:["produce descendencia a partir de un solo individuo, sin necesitar pareja.","mezcla características genéticas de dos individuos diferentes.","solo ocurre en organismos pluricelulares complejos."],correct:0,mepBloque:"biodiversidad"},{stimulus:"En las selvas de Costa Rica, la gran diversidad de altitudes y relieves crea diferentes microhábitats. En cada uno de estos microhábitats viven especies específicas que han desarrollado adaptaciones para sobrevivir en esas condiciones particulares.",source:"SINAC, Sistema Nacional de Áreas de Conservación.",question:"El espacio específico dentro de un ecosistema que ocupa una especie y que incluye sus condiciones particulares de vida se llama",options:["comunidad.","nicho ecológico.","hábitat."],correct:1,mepBloque:"biodiversidad"},{stimulus:"Durante las migraciones, muchas especies de aves recorren miles de kilómetros guiándose por las estrellas, el Sol o el campo magnético de la Tierra. Este comportamiento les permite llegar a regiones cálidas cuando el frío llega a su lugar de origen.",source:"Atlas de Fauna Costarricense.",question:"La migración de las aves es un ejemplo de adaptación relacionada con",options:["la alimentación.","la defensa contra depredadores.","la respuesta a cambios ambientales para sobrevivir."],correct:2,mepBloque:"biodiversidad"},{stimulus:"El ser humano también pertenece al reino animal. Al igual que otros mamíferos, el ser humano es un organismo pluricelular, heterótrofo, con núcleo celular definido y con la capacidad de desplazarse de un lugar a otro.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, el ser humano se clasifica dentro del reino",options:["Protista.","Plantae.","Animalia."],correct:2,mepBloque:"biodiversidad"},{stimulus:"En clase de Ciencias están estudiando las formas en que el calor se transmite de un cuerpo a otro. El maestro explica que cuando un metal se calienta en un extremo, el calor viaja a lo largo del material hasta que todo el objeto alcanza la misma temperatura.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La forma de transmisión del calor que describe el texto se llama",options:["convección.","radiación.","conducción."],correct:2,mepBloque:"energia"},{stimulus:"Cuando el Sol calienta la superficie de la Tierra, no necesita ningún material sólido ni líquido para transferir su energía. Esta forma de transmisión del calor puede viajar incluso a través del vacío del espacio exterior.",source:"Libro de Ciencias, Morfho Editorial.",question:"La forma de transmisión del calor descrita en el texto se llama",options:["conducción.","convección.","radiación."],correct:2,mepBloque:"energia"},{stimulus:"En un experimento, los estudiantes observaron que al calentar agua en una olla, el agua del fondo sube cuando se calienta y el agua más fría baja, creando un movimiento circular continuo que distribuye el calor de manera uniforme en el líquido.",source:"Libro de Ciencias, Morfho Editorial.",question:"La forma de transmisión del calor observada en el experimento se llama",options:["conducción.","convección.","radiación."],correct:1,mepBloque:"energia"},{stimulus:"Cuando un rayo de luz pasa de un medio a otro de diferente densidad, como del aire al agua, cambia de velocidad y en algunos casos cambia de dirección. Este fenómeno es el que hace que un lápiz parezca doblarse cuando se introduce en un vaso con agua.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El fenómeno descrito en el texto se llama",options:["reflexión.","refracción.","descomposición."],correct:1,mepBloque:"energia"},{stimulus:"Cuando la luz solar pasa a través de un prisma de vidrio, el rayo blanco se descompone en los colores del arco iris: rojo, anaranjado, amarillo, verde, azul, índigo y violeta. El mismo fenómeno ocurre cuando la lluvia descompone la luz solar en el cielo.",source:"Libro de Ciencias, Morfho Editorial.",question:"El fenómeno que produce el arco iris y que consiste en la separación de la luz blanca en sus colores se llama",options:["refracción.","reflexión.","descomposición de la luz."],correct:2,mepBloque:"energia"},{stimulus:"Un espejo plano devuelve la luz que llega a su superficie hacia el mismo lado de donde provino. Gracias a este fenómeno podemos ver nuestra imagen cuando nos miramos en un espejo.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El fenómeno que describe el texto, en el que la luz rebota sobre una superficie y regresa hacia su origen, se llama",options:["reflexión.","refracción.","conducción."],correct:0,mepBloque:"energia"},{stimulus:"Un objeto es transparente cuando deja pasar la luz completamente a través de él, permitiendo ver con claridad los objetos del otro lado. El vidrio de una ventana limpia es un ejemplo de este tipo de material.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, el vidrio de una ventana limpia se clasifica como un material",options:["transparente.","translúcido.","opaco."],correct:0,mepBloque:"energia"},{stimulus:"Las lentes de los anteojos aprovechan las propiedades de la luz para corregir problemas de visión. Dependiendo del tipo de problema, la lente puede hacer que los rayos de luz converjan o diverjan antes de entrar al ojo, lo que mejora la calidad de la imagen que percibe la persona.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El fenómeno de la luz que aprovechan las lentes de los anteojos para corregir la visión es la",options:["reflexión.","refracción.","descomposición."],correct:1,mepBloque:"energia"},{stimulus:"En un experimento escolar, los estudiantes construyeron un molinillo de papel y lo colocaron frente a un ventilador. Observaron que el movimiento del aire hacía girar el molinillo. La energía del molinillo en movimiento se llama energía de movimiento.",source:"Libro de Ciencias, Morfho Editorial.",question:"La energía que posee el molinillo cuando está girando, debida a su movimiento, se llama energía",options:["potencial.","química.","cinética."],correct:2,mepBloque:"energia"},{stimulus:"Un esquiador en la cima de una montaña, antes de empezar a descender, posee una forma de energía almacenada relacionada con su posición elevada. Mientras más alta sea la montaña, mayor será esta energía almacenada.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La energía que posee el esquiador en la cima de la montaña, antes de empezar el descenso, se llama energía",options:["potencial.","cinética.","solar."],correct:0,mepBloque:"energia"},{stimulus:"Las plantas almacenan la energía del Sol en sus frutos y semillas en forma de azúcares. Cuando los animales o las personas comen esos alimentos, su cuerpo libera la energía almacenada en ellos para utilizarla en sus actividades diarias.",source:"Libro de Ciencias, Morfho Editorial.",question:"La energía almacenada en los alimentos que el cuerpo libera al digerirlos es la energía",options:["cinética.","eléctrica.","química."],correct:2,mepBloque:"energia"},{stimulus:"Las centrales geotérmicas aprovechan el calor del interior de la Tierra para generar electricidad. En Costa Rica, el volcán Miravalles alberga una de las plantas geotérmicas más importantes del país.",source:"Instituto Costarricense de Electricidad, ICE.",question:"Según el texto, la energía que aprovechan las plantas geotérmicas proviene del",options:["movimiento del viento.","calor del Sol.","calor del interior de la Tierra."],correct:2,mepBloque:"energia"},{stimulus:"Los combustibles fósiles como el petróleo, el carbón y el gas natural se formaron hace millones de años a partir de restos de seres vivos. Existen en cantidades limitadas y al quemarse liberan gases que contribuyen al efecto invernadero.",source:"Ministerio de Ambiente y Energía, MINAE.",question:"Según el texto, los combustibles fósiles se consideran una fuente de energía no renovable porque",options:["producen electricidad de manera eficiente.","existen en cantidades limitadas y no pueden regenerarse.","son capaces de funcionar sin contaminar el ambiente."],correct:1,mepBloque:"energia"},{stimulus:"Las fuentes de energía renovables tienen la capacidad de regenerarse de manera natural en períodos de tiempo relativamente cortos. Son consideradas amigables con el ambiente porque no producen gases de efecto invernadero al ser utilizadas.",source:"Instituto Costarricense de Electricidad, ICE.",question:"Según el texto, una característica que diferencia las fuentes de energía renovables de las no renovables es que las renovables",options:["producen más electricidad que las no renovables.","pueden regenerarse de manera natural y no contaminan.","solo pueden utilizarse en países desarrollados."],correct:1,mepBloque:"energia"},{stimulus:"Costa Rica genera la mayor parte de su electricidad a partir de fuentes limpias. El agua de los ríos es utilizada en represas para generar electricidad, lo que convierte al país en un referente mundial en el uso de energías limpias.",source:"Instituto Costarricense de Electricidad, ICE.",question:"Según el texto, el tipo de energía que se genera a partir de la fuerza del agua en las represas costarricenses se llama energía",options:["solar.","eólica.","hidroeléctrica."],correct:2,mepBloque:"energia"},{stimulus:"En una feria científica, un estudiante demostró que al encender una lámpara, la energía eléctrica que llega a ella se transforma en dos formas de energía diferentes: una que permite ver en la oscuridad y otra que se siente como calor al acercar la mano.",source:"Libro de Ciencias, Morfho Editorial.",question:"Las dos formas de energía en las que se transforma la energía eléctrica al encender una lámpara son",options:["cinética y sonora.","química y eólica.","lumínica y calorífica."],correct:2,mepBloque:"energia"},{stimulus:"Los circuitos eléctricos tienen elementos básicos que los componen. Uno de estos elementos es el encargado de producir o suministrar la energía eléctrica necesaria para que los otros componentes del circuito funcionen. Las baterías o pilas son un ejemplo de este elemento.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El elemento del circuito eléctrico que suministra la energía es el",options:["generador.","interruptor.","conductor."],correct:0,mepBloque:"energia"},{stimulus:"En un circuito eléctrico, si uno de los bombillos se funde, todos los demás se apagan también, porque solo existe un camino para que la corriente eléctrica circule. Las luces navideñas antiguas funcionaban de esta manera.",source:"Libro de Ciencias, Morfho Editorial.",question:"El tipo de circuito que se describe en el texto se llama circuito",options:["en serie.","en paralelo.","alterno."],correct:0,mepBloque:"energia"},{stimulus:"En el tipo de circuito eléctrico que se usa en las casas, si una bombilla se funde, las demás continúan funcionando normalmente porque la electricidad tiene varios caminos independientes para llegar a cada dispositivo.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El tipo de circuito que se usa en las casas y que permite que cada dispositivo funcione de forma independiente se llama circuito",options:["en serie.","en paralelo.","continuo."],correct:1,mepBloque:"energia"},{stimulus:"Las cargas eléctricas positivas y negativas interactúan entre sí de una manera predecible: cuando dos cargas tienen el mismo signo, se empujan; cuando tienen signos diferentes, se atraen.",source:"Libro de Ciencias, Morfho Editorial.",question:"Según el texto, cuando dos cargas eléctricas tienen signos opuestos (una positiva y una negativa),",options:["no ocurre ninguna interacción entre ellas.","se repelen mutuamente.","se atraen mutuamente."],correct:2,mepBloque:"energia"},{stimulus:"La energía eólica aprovecha el movimiento del viento para hacer girar grandes aspas unidas a un generador que convierte ese movimiento en electricidad. Esta energía no produce gases contaminantes y es inagotable.",source:"Instituto Costarricense de Electricidad, ICE.",question:"Según el texto, la energía eólica se produce a partir de",options:["el calor del Sol.","la fuerza del viento.","el movimiento del agua en los ríos."],correct:1,mepBloque:"energia"},{stimulus:"La energía nuclear se obtiene de reacciones que ocurren en el núcleo de los átomos. Si bien no produce emisiones de dióxido de carbono directamente, genera residuos radiactivos que son difíciles de almacenar de forma segura.",source:"Ministerio de Ambiente y Energía, MINAE.",question:"Según el texto, el principal problema ambiental de la energía nuclear es que",options:["produce grandes cantidades de dióxido de carbono.","genera residuos radiactivos de difícil manejo.","depende de condiciones climáticas variables para funcionar."],correct:1,mepBloque:"energia"},{stimulus:"Un panel solar instalado en el techo de una casa capta la luz del Sol y la convierte en electricidad. Este proceso representa una transformación de un tipo de energía en otro tipo de energía diferente.",source:"Instituto Costarricense de Electricidad, ICE.",question:"Según la información anterior, la transformación de energía que ocurre en el panel solar es de energía",options:["química a eléctrica.","cinética a lumínica.","solar a eléctrica."],correct:2,mepBloque:"energia"},{stimulus:"La corriente eléctrica que se utiliza en los hogares y que se genera en las plantas eléctricas cambia de dirección constantemente y a gran velocidad. Esta característica la diferencia de la corriente que producen las baterías.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La corriente eléctrica que cambia de dirección de manera continua y que se usa en los hogares se llama corriente",options:["alterna.","continua.","estática."],correct:0,mepBloque:"energia"},{stimulus:"La energía que almacenan los alimentos que consumimos es fundamental para que el cuerpo pueda realizar todas sus funciones vitales. Cuando el cuerpo utiliza esa energía para moverse, trabaja o genera calor, se produce una transformación de energía.",source:"Ministerio de Salud de Costa Rica.",question:"La transformación de energía que ocurre cuando el cuerpo utiliza los nutrientes de los alimentos para moverse es de energía",options:["eléctrica a térmica.","química a cinética.","lumínica a química."],correct:1,mepBloque:"energia"},{stimulus:"La Tierra está formada por capas concéntricas. La capa más externa, sobre la que vivimos y en la que se encuentran los continentes y los fondos oceánicos, es la más delgada de todas las capas del planeta.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La capa más externa de la Tierra descrita en el texto se llama",options:["manto.","núcleo.","corteza."],correct:2,mepBloque:"geofisica"},{stimulus:"En el interior de la Tierra existe una capa formada por roca fundida y materiales en estado semisólido, que se encuentra entre la corteza terrestre y el núcleo. Esta capa es la más gruesa del planeta.",source:"Libro de Ciencias, Morfho Editorial.",question:"La capa del interior de la Tierra descrita en el texto es el",options:["núcleo externo.","manto.","núcleo interno."],correct:1,mepBloque:"geofisica"},{stimulus:"La teoría de la tectónica de placas explica que la corteza terrestre está dividida en grandes fragmentos que flotan sobre el manto y se desplazan lentamente. El encuentro o separación de estos fragmentos genera fenómenos geológicos importantes.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Los grandes fragmentos de la corteza terrestre que se desplazan lentamente sobre el manto se llaman",options:["fallas geológicas.","placas tectónicas.","capas tectónicas."],correct:1,mepBloque:"geofisica"},{stimulus:"En las zonas donde dos placas tectónicas colisionan, una de ellas puede hundirse bajo la otra. Al hundirse, el material se funde y puede ascender a la superficie a través de aberturas en la corteza terrestre, creando estructuras volcánicas.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"Según el texto, los volcanes se forman principalmente como resultado del",options:["movimiento de rotación de la Tierra.","enfriamiento del núcleo terrestre.","desplazamiento y colisión de las placas tectónicas."],correct:2,mepBloque:"geofisica"},{stimulus:"Los terremotos son vibraciones que se producen en la corteza terrestre como resultado del movimiento repentino de las rocas a lo largo de fracturas o fallas geológicas. La energía liberada se propaga en todas direcciones en forma de ondas.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"Las vibraciones que viajan a través de la corteza terrestre durante un terremoto se llaman",options:["erupciones.","ondas sísmicas.","mareas."],correct:1,mepBloque:"geofisica"},{stimulus:"La escala Richter es un instrumento de medición que permite cuantificar la magnitud de la energía liberada durante un terremoto. Fue diseñada por el científico Charles Richter en 1935 y se usa ampliamente en sismología.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"Según la información anterior, la escala Richter se utiliza para medir",options:["la profundidad a la que se origina un terremoto.","la velocidad de desplazamiento de las placas tectónicas.","la magnitud de la energía liberada en un terremoto."],correct:2,mepBloque:"geofisica"},{stimulus:"La Tierra realiza un movimiento sobre su propio eje imaginario que dura aproximadamente 24 horas. Como resultado de este movimiento, las partes del planeta que están orientadas hacia el Sol reciben luz y calor, mientras que las que están de espaldas quedan en oscuridad.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El movimiento de la Tierra sobre su propio eje que origina el día y la noche se llama movimiento de",options:["rotación.","traslación.","revolución."],correct:0,mepBloque:"geofisica"},{stimulus:"La Tierra también realiza un recorrido alrededor del Sol a lo largo de un año. Durante este recorrido, la inclinación del eje terrestre provoca que diferentes partes del planeta reciban más o menos luz solar en distintas épocas del año.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"El movimiento de la Tierra alrededor del Sol que origina las estaciones del año se llama movimiento de",options:["rotación.","traslación.","precesión."],correct:1,mepBloque:"geofisica"},{stimulus:"La atmósfera terrestre está compuesta por varias capas de gases que envuelven al planeta. La capa más cercana a la superficie, donde ocurren los fenómenos meteorológicos como las lluvias, los vientos y las tormentas, recibe un nombre específico.",source:"Instituto Meteorológico Nacional.",question:"La capa de la atmósfera más cercana a la superficie donde ocurren los fenómenos del tiempo se llama",options:["tropósfera.","estratósfera.","mesósfera."],correct:0,mepBloque:"geofisica"},{stimulus:"La Luna realiza dos movimientos simultáneos: uno en el que gira sobre su propio eje y otro en el que da una vuelta completa alrededor de la Tierra. La duración de ambos movimientos es prácticamente igual, lo que explica por qué siempre vemos la misma cara de la Luna desde la Tierra.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Según el texto, el movimiento de la Luna alrededor de la Tierra se llama",options:["rotación lunar.","traslación lunar.","revolución solar."],correct:1,mepBloque:"geofisica"},{stimulus:"Las fases de la Luna son los distintos aspectos que presenta desde la Tierra a medida que avanza en su órbita alrededor del planeta. Estas fases se producen porque la parte iluminada por el Sol que podemos ver varía con su posición relativa.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"Las fases de la Luna se producen por cambios en",options:["el tamaño real de la Luna en su órbita.","la distancia entre la Tierra y el Sol.","la porción de la Luna iluminada por el Sol que vemos desde la Tierra."],correct:2,mepBloque:"geofisica"},{stimulus:"El sistema solar está formado por una estrella central y todos los objetos que orbitan a su alrededor gracias a la fuerza de gravedad. Entre esos objetos se encuentran los planetas, sus satélites, los cometas y los asteroides.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La estrella que ocupa el centro del sistema solar y alrededor de la cual orbitan los planetas es el",options:["Sol.","cometa.","asteroide."],correct:0,mepBloque:"geofisica"},{stimulus:"Las galaxias son enormes agrupaciones de estrellas, gas y polvo cósmico que se mantienen unidas por la fuerza de gravedad. La galaxia en la que se encuentra nuestro sistema solar recibe un nombre particular.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La galaxia en la que se encuentra nuestro sistema solar se llama",options:["Andrómeda.","Gran Nube de Magallanes.","Vía Láctea."],correct:2,mepBloque:"geofisica"},{stimulus:"Un terremoto de alta magnitud en el fondo del océano puede desplazar grandes volúmenes de agua, generando olas gigantes que viajan a gran velocidad hacia las costas. Estas olas pueden causar grandes destrucciones al llegar a tierra firme.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"Las olas gigantes generadas por terremotos submarinos que describe el texto se llaman",options:["huracanes.","tormentas.","tsunamis."],correct:2,mepBloque:"geofisica"},{stimulus:"En Costa Rica, la Cordillera Volcánica Central, que incluye volcanes como el Poás, el Irazú y el Turrialba, fue formada por la actividad de las placas tectónicas a lo largo de millones de años. Esta actividad continua sigue modificando el relieve del territorio nacional.",source:"OVSICORI, Observatorio Vulcanológico de Costa Rica.",question:"Según el texto, la formación de la Cordillera Volcánica Central de Costa Rica se debe a",options:["los movimientos de rotación y traslación de la Tierra.","la acumulación de sedimentos en el fondo del océano.","la actividad de las placas tectónicas a lo largo del tiempo."],correct:2,mepBloque:"geofisica"}],p=a=>a.map(o=>({...T[o]})),U=p([1,4,7,10,13,16,18,21,24,27,30,31,35,38,41,44,47,50,53,56,59,61,64,67,70,73,76,79,82,85,86,90,93,96,99]),F=p([2,5,8,11,14,17,20,23,26,29,32,34,37,40,43,46,48,51,54,57,60,62,65,68,71,74,77,80,83,87,89,92,94,97,100]),J=p([3,6,9,12,15,19,22,25,28,33,36,39,42,45,49,52,55,58,63,66,69,72,75,78,81,84,88,91,95,98]),O=[{stimulus:"La sangre es un tejido líquido formado por varios componentes. Uno de ellos es un líquido amarillento compuesto por agua, sales, proteínas y vitaminas que sirve para transportar las células sanguíneas por todo el cuerpo.",source:"Ministerio de Educación Pública de Costa Rica.",question:"De acuerdo con la información anterior, el componente de la sangre que se describe es el",options:["plasma.","glóbulo rojo.","glóbulo blanco."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"Una estudiante de sexto grado se realizó un examen de sangre. El médico le explicó que cuando el organismo está combatiendo una infección causada por bacterias, la cantidad de un tipo de célula sanguínea aumenta considerablemente para defender el cuerpo.",source:"Guía de Salud Escolar, MEP.",question:"Según la información anterior, las células cuya cantidad aumenta durante una infección son los",options:["glóbulos blancos.","glóbulos rojos.","trombocitos."],correct:0,mepBloque:"cuerpo-humano"},{stimulus:"La biodiversidad se refiere a la variedad de seres vivos que existe en un lugar determinado. Costa Rica es uno de los países con mayor riqueza biológica del mundo gracias a factores como su posición geográfica y la variedad de sus ecosistemas.",source:"SINAC, Sistema Nacional de Áreas de Conservación.",question:"Según el texto, el término que hace referencia a la variedad de seres vivos en un lugar es",options:["biodiversidad.","nicho ecológico.","ecosistema."],correct:0,mepBloque:"biodiversidad"},{stimulus:"En clase de Ciencias están estudiando las formas en que el calor se transmite de un cuerpo a otro. El maestro explica que cuando un metal se calienta en un extremo, el calor viaja a lo largo del material hasta que todo el objeto alcanza la misma temperatura.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La forma de transmisión del calor que describe el texto se llama",options:["conducción.","convección.","radiación."],correct:0,mepBloque:"energia"},{stimulus:"La Tierra está formada por capas concéntricas. La capa más externa, sobre la que vivimos y en la que se encuentran los continentes y los fondos oceánicos, es la más delgada de todas las capas del planeta.",source:"Guía de Ciencias, Primaria Diurna, MEP.",question:"La capa más externa de la Tierra descrita en el texto se llama",options:["corteza.","manto.","núcleo."],correct:0,mepBloque:"geofisica"}],V=[...J,...O],k=[U,F,V],d={sociales:A,ciencias:k},w=Object.keys(d),W=(a,o)=>o.bloques.map(s=>({id:s.id,label:s.label,count:a.filter(i=>i.mepBloque===s.id).length})).filter(s=>s.count>0),Q=()=>{const{subject:a,examIndex:o}=B(),s=S[a],i=parseInt(o,10)-1,[g,c]=r.useState("start"),[f,u]=r.useState({}),[v,q]=r.useState(0),n=r.useRef(null);if(r.useEffect(()=>{c("start"),u({}),q(0),n.current=null},[o]),!w.includes(a)||!s)return l.jsx(b,{to:"/",replace:!0});if(isNaN(i)||i<0||i>=d[a].length)return l.jsx(b,{to:"/",replace:!0});const t=d[a][i],C=`Examen Extra ${o}`,y=()=>{n.current=Date.now(),c("active")},E=h=>{const L=n.current?Math.floor((Date.now()-n.current)/1e3):0;u(h),q(L),c("results")},x=()=>{n.current=null,u({}),c("start")};return g==="start"?l.jsx(R,{config:s,subtitle:C,questionCount:t.length,bloqueBreakdown:W(t,s),onStart:y}):g==="active"?l.jsx(j,{questions:t,onFinish:E}):l.jsx(z,{questions:t,answers:f,timeUsed:v,subject:a,onRestart:x})};export{Q as default};
